    def seed_tariffs_and_builders(self):
        import test_pm_lease_lessee_persistence as loader
        self.session.execute(text('CREATE TEMP TABLE bil_tariff(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,utility_type text,code text,description text,rate numeric,block_start numeric,block_end numeric,reduction_factor numeric,unit text,effective_date text)'))
        self.session.execute(text("INSERT INTO bil_tariff(utility_type,code,description,rate,unit,effective_date) VALUES('electricity','ELEC01','Electricity',3.2795,'R/kWh','2026-01-01'),('water_fixed','W_LOSS','Water Loss Charge',19.30,'R/month','2026-06-05'),('water_fixed','W_MGT','Management Fee',144.54,'R/month','2026-06-05'),('sewerage_fixed','S_REFUSE','Refuse',206.93,'R/month','2026-06-05')"))
        for kind,codes,rates,factors,starts,ends in [('water',['W01','W02','W03','W04','W05'],['39.39','46.70','62.17','95.91','105.39'],['.2','.633','.167','.5','999'],[0,201,834,1001,1501],[200,833,1000,1500,None]),('sewerage',['S01','S02','S03','S04'],['5.45','9.20','17.54','27.38'],['.2','.633','.167','999'],[0,201,834,1001],[200,833,1000,None])]:
            for code,rate,factor,start,end in zip(codes,rates,factors,starts,ends):
                self.session.execute(text("INSERT INTO bil_tariff(utility_type,code,description,rate,block_start,block_end,reduction_factor,unit,effective_date) VALUES(:u,:c,:c,:r,:s,:e,:f,'kL/day','2026-06-05')"),dict(u=kind,c=code,r=rate,s=start,e=end,f=factor))
        self.session.commit();self.conn.commit()
        from app.program_billing import metsoa_tariffs
        mock=patch.object(metsoa_tariffs,'db',self.db);mock.start();self.addCleanup(mock.stop)
        env={};loader.functions('app/program_billing/routes.py',{'build_electrical_rows','build_water_rows','build_ws_sd_rows_for_meter','build_ws_breakdown','build_sd_breakdown','build_water_fee_block'},env)
        self.original_env=env
        mock=patch.object(self.metsoa,'original_builders',return_value=(env['build_electrical_rows'],env['build_water_rows']));mock.start();self.addCleanup(mock.stop)
    def test_original_builders_use_canonical_pairs_and_do_not_read_reconciliation(self):
        before=self.snapshot();queries=[]
        def record(conn,cursor,sql,params,context,many):queries.append(sql.lower())
        event.listen(self.conn,'before_cursor_execute',record)
        try:
            with self.app.test_request_context():data=self.metsoa.build(26,'2026-10',recipient_id=11)
            page=self.client.get(self.generation_url,headers=self.headers);self.assertEqual(page.status_code,200,page.text)
            self.assertEqual(self.client.get(self.generation_url,headers=self.headers).status_code,200)
        finally:event.remove(self.conn,'before_cursor_execute',record)
        elec={r['meter_number']:r for r in data['electricity']['rows']};water={r['meter_number']:r for r in data['water']['meters']}
        self.assertEqual(elec['7150696S']['consumption'],15);self.assertEqual(elec['2188802S']['consumption'],547)
        self.assertEqual(water['CEL888']['summary']['consumption'],31);self.assertEqual(water['CXN998']['summary']['consumption'],1)
        self.assertEqual(elec['7150696S']['last_date'],'2026/08/26');self.assertEqual(water['CEL888']['summary']['new_date'],'2026/10/23')
        self.assertEqual(data['electricity']['subtotal'],Decimal('1843.08'));self.assertFalse(data['pm_complete'])
        self.assertIn('ANG489: Only one reading',str(data['pm_issues']));self.assertNotIn('surcharge tariff',str(data['pm_issues']))
        self.assertIn('Statement For All Metro Meters',page.text);self.assertIn('Electricity Sub-Total',page.text);self.assertIn('W&S For #',page.text);self.assertIn('S & D Cost',page.text)
        self.assertIn('NOT A FINAL AMOUNT DUE',page.text);self.assertNotIn('Arrears',page.text);self.assertNotIn('7,190.88',page.text)
        self.assertFalse(any(q.lstrip().startswith(('insert ','update ','delete ')) for q in queries))
        self.assertFalse(any('bil_municipal_statement' in q or 'bil_muni_payment' in q or 'bil_statement_payment' in q or 'bil_consumption' in q for q in queries));self.assertEqual(before,self.snapshot())
    def test_valid_explicit_surcharges_and_second_reading_enable_final_amount(self):
        self.session.execute(text("INSERT INTO bil_tariff(utility_type,code,description,rate,unit,effective_date) VALUES('water','WSSurcharge','Recorded water surcharge',1.48,'R/kL','2026-06-05'),('sewerage','SDSurcharge','Recorded sewerage surcharge',1.48,'R/kL','2026-06-05')"))
        self.session.execute(text("INSERT INTO bil_meter_reading(meter_id,reading_date,reading_value) VALUES(5,'2026-09-25',10)"));self.session.commit();self.conn.commit()
        with self.app.test_request_context():data=self.metsoa.build(26,'2026-10',recipient_id=11)
        self.assertTrue(data['pm_complete'],data['pm_issues'])
        page=self.client.get(self.generation_url,headers=self.headers);self.assertNotIn('NOT A FINAL AMOUNT DUE',page.text);self.assertIn('Amount Due R',page.text)
    def test_effective_rates_ignore_future_records_and_detect_ambiguous_or_missing(self):
        self.session.execute(text("INSERT INTO bil_tariff(utility_type,code,rate,effective_date) VALUES('electricity','ELEC01',99,'2027-01-01')"));self.session.commit();self.conn.commit()
        with self.app.test_request_context():data=self.metsoa.build(26,'2026-10',recipient_id=11)
        self.assertEqual(data['electricity']['rows'][0]['rate'],Decimal('3.2795'))
        self.session.execute(text("INSERT INTO bil_tariff(utility_type,code,rate,effective_date) VALUES('electricity','ELEC01',8,'2026-01-01')"));self.session.commit();self.conn.commit()
        with self.app.test_request_context():data=self.metsoa.build(26,'2026-10',recipient_id=11)
        self.assertEqual(data['electricity']['rows'],[]);self.assertIn('conflicting records',str(data['pm_issues']))
        self.session.execute(text("DELETE FROM bil_tariff WHERE utility_type IN ('water','water_fixed')"));self.session.commit();self.conn.commit()
        with self.app.test_request_context():data=self.metsoa.build(26,'2026-10',recipient_id=11)
        self.assertEqual(data['water']['meters'],[]);self.assertIn('No applicable water',str(data['pm_issues']))
